import { CURATED_STACKS, type CuratedStack } from "@/data/stacks";
import type { Item } from "@/data/items";

const CATEGORIES = ["all", "Websites", "Softwares", "Scripts", "stacks", "favorites"];

export function readCatalogUrl(url: URL, items: readonly Item[]) {
  const params = url.searchParams;
  const stackId = params.get("stack");
  let stack = CURATED_STACKS.find((entry) => entry.id === stackId) ?? null;
  // Continue supporting stack links generated by earlier versions of the site.
  if (!stack && url.hash.startsWith("#stack=")) {
    const ids = decodeURIComponent(url.hash.slice(7)).split(",");
    stack = CURATED_STACKS.find((entry) => entry.itemIds.length === ids.length && entry.itemIds.every((id) => ids.includes(id))) ?? null;
  }
  const category = params.get("category") ?? "all";
  const toolId = params.get("tool") || (!url.hash.startsWith("#stack=") ? url.hash.slice(1) : null);
  return {
    query: params.get("q") ?? "",
    category: stack ? "stacks" : CATEGORIES.includes(category) ? category : "all",
    tag: params.get("tag") ?? "all",
    stack,
    tool: items.find((item) => item.id === toolId) ?? null,
  };
}

export function stackShareUrl(origin: string, stack: CuratedStack) {
  const url = new URL("/", origin);
  url.searchParams.set("category", "stacks");
  url.searchParams.set("stack", stack.id);
  return url.toString();
}
